"use client"

import React, { useState } from 'react'
import { Button } from '@/components/ui/Button'
import { Phone, Mail, MapPin, Send } from 'lucide-react'

export default function ContactPage() {
  const [formStatus, setFormStatus] = useState<'idle' | 'sending' | 'sent'>('idle')

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    setFormStatus('sending')
    setTimeout(() => setFormStatus('sent'), 1500)
  }

  return (
    <div className="min-h-screen pt-40 pb-32 bg-[var(--bg-primary)]">
      <div className="max-w-[1400px] mx-auto px-6 lg:px-20 grid grid-cols-1 lg:grid-cols-2 gap-20">
        
        {/* Left Info */}
        <div className="space-y-12">
           <div className="space-y-6">
              <span className="text-xs font-bold uppercase tracking-[0.4em] text-[var(--accent-earth)]">Get in touch</span>
              <h1 className="text-[var(--text-xl)] font-black tracking-tighter leading-none font-heading">Let's plan your <span className="text-transparent bg-clip-text bg-gradient-to-r from-[var(--accent-earth)] to-[var(--accent-gold)]">dream trip.</span></h1>
              <p className="text-lg text-[var(--text-secondary)] max-w-md">
                Have questions about our premium packages? Our travel connoisseurs are here to assist you.
              </p>
           </div>

           <div className="space-y-8">
              <div className="flex gap-6 items-start">
                 <div className="w-14 h-14 rounded-full glass flex items-center justify-center shrink-0 text-[var(--accent-earth)]">
                    <Phone className="w-6 h-6" />
                 </div>
                 <div>
                    <h4 className="font-bold text-sm uppercase tracking-widest text-[var(--text-muted)] mb-1">Call Us</h4>
                    <p className="text-xl font-black">+91 99998 08162</p>
                 </div>
              </div>

              <div className="flex gap-6 items-start">
                 <div className="w-14 h-14 rounded-full glass flex items-center justify-center shrink-0 text-[var(--accent-earth)]">
                    <Mail className="w-6 h-6" />
                 </div>
                 <div>
                    <h4 className="font-bold text-sm uppercase tracking-widest text-[var(--text-muted)] mb-1">Email Support</h4>
                    <p className="text-xl font-black">hello@ghumoholidays.com</p>
                 </div>
              </div>

              <div className="flex gap-6 items-start">
                 <div className="w-14 h-14 rounded-full glass flex items-center justify-center shrink-0 text-[var(--accent-earth)]">
                    <MapPin className="w-6 h-6" />
                 </div>
                 <div>
                    <h4 className="font-bold text-sm uppercase tracking-widest text-[var(--text-muted)] mb-1">Office</h4>
                    <p className="text-xl font-black">New Delhi, India</p>
                 </div>
              </div>
           </div>
        </div>

        {/* Right Form */}
        <div className="glass p-12 rounded-[4rem] border-white/50 shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-[var(--accent-earth)]/5 rounded-full blur-3xl"></div>
          
          <form className="relative z-10 space-y-6" onSubmit={handleSubmit}>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
               <div className="space-y-2">
                  <label className="text-[10px] font-bold uppercase tracking-widest px-4">Full Name</label>
                  <input type="text" required placeholder="John Doe" className="w-full bg-white/50 border border-black/5 rounded-2xl px-6 py-4 focus:outline-none focus:ring-2 focus:ring-[var(--accent-earth)]/20 transition-all font-medium" />
               </div>
               <div className="space-y-2">
                  <label className="text-[10px] font-bold uppercase tracking-widest px-4">Email Address</label>
                  <input type="email" required placeholder="john@example.com" className="w-full bg-white/50 border border-black/5 rounded-2xl px-6 py-4 focus:outline-none focus:ring-2 focus:ring-[var(--accent-earth)]/20 transition-all font-medium" />
               </div>
            </div>

            <div className="space-y-2">
               <label className="text-[10px] font-bold uppercase tracking-widest px-4">Subject</label>
               <select className="w-full bg-white/50 border border-black/5 rounded-2xl px-6 py-4 focus:outline-none focus:ring-2 focus:ring-[var(--accent-earth)]/20 transition-all font-medium">
                  <option>Booking Inquiry</option>
                  <option>Package Customization</option>
                  <option>Partnership</option>
                  <option>Other</option>
               </select>
            </div>

            <div className="space-y-2">
               <label className="text-[10px] font-bold uppercase tracking-widest px-4">Your Message</label>
               <textarea rows={4} required placeholder="Tell us about your dream destination..." className="w-full bg-white/50 border border-black/5 rounded-2xl px-6 py-4 focus:outline-none focus:ring-2 focus:ring-[var(--accent-earth)]/20 transition-all font-medium resize-none"></textarea>
            </div>

            <Button 
              type="submit" 
              variant="primary" 
              magnetic 
              className="w-full !rounded-2xl flex gap-3 items-center justify-center py-6"
              disabled={formStatus !== 'idle'}
            >
              {formStatus === 'idle' && <><Send className="w-4 h-4" /> Send Message</>}
              {formStatus === 'sending' && "Sending..."}
              {formStatus === 'sent' && "Message Sent!"}
            </Button>
          </form>
        </div>
      </div>
    </div>
  )
}
